#include <moe_topk/protocol_i_benes.h>
#include <map>
#include <stdexcept>
namespace moe_topk { namespace {
bool power(std::uint32_t x){return x>=2&&(x&(x-1))==0;} std::uint32_t lg(std::uint32_t x){std::uint32_t r=0;while(x>1){++r;x>>=1;}return r;}
void route(std::uint32_t depth,std::uint32_t bits,const std::vector<std::pair<std::uint32_t,std::uint32_t>>& map,std::vector<ProtocolIPermutation>& stages){if(depth==bits){for(auto e:map)if(e.first!=e.second)throw std::logic_error("Benes identity");return;}const auto bit=UINT32_C(1)<<(bits-depth-1),first=depth,last=2*bits-depth-2;if(depth+1==bits){for(auto e:map){if((e.first&~bit)!=(e.second&~bit))throw std::logic_error("Benes centre");stages[first][e.second]=e.first;}return;}struct E{std::uint32_t in,out;int c=-1;};std::vector<E> edges;std::map<std::pair<int,std::uint32_t>,std::vector<std::size_t>> inc;for(auto e:map){auto k=edges.size();edges.push_back({e.first,e.second});inc[{0,e.first&~bit}].push_back(k);inc[{1,e.second&~bit}].push_back(k);}for(auto&v:inc)if(v.second.size()!=2)throw std::logic_error("Benes degree");for(std::size_t s=0;s<edges.size();++s)if(edges[s].c<0){edges[s].c=0;std::vector<std::size_t>q{s};for(std::size_t z=0;z<q.size();++z){auto e=edges[q[z]];for(auto k:{std::pair<int,std::uint32_t>{0,e.in&~bit},{1,e.out&~bit}}){auto&v=inc.at(k);const auto other=v[0]==q[z]?v[1]:v[0];const int want=1-e.c;if(edges[other].c<0){edges[other].c=want;q.push_back(other);}else if(edges[other].c!=want)throw std::logic_error("Benes colour");}}}auto sw=[&](ProtocolIPermutation&p,std::uint32_t base,bool yes){if(yes){p[base]=base|bit;p[base|bit]=base;}};std::vector<std::pair<std::uint32_t,std::uint32_t>> inner[2];for(auto&e:edges){const auto a=(e.in&~bit)|(e.c?bit:0);const auto b=(e.out&~bit)|(e.c?bit:0);sw(stages[first],e.in&~bit,e.in!=a);sw(stages[last],e.out&~bit,e.out!=b);inner[e.c].push_back({a,b});}route(depth+1,bits,inner[0],stages);route(depth+1,bits,inner[1],stages);}
}
ProtocolIBenesLayout protocol_i_benes_layout(std::uint32_t n,std::uint32_t t){if(!power(n)||!power(t)||t>n||lg(n)%lg(t))throw std::invalid_argument("Benes shape");const auto ln=lg(n),lt=lg(t),d=2*(ln/lt)-1;ProtocolIBenesLayout r{n,t,d,{}};std::vector<std::uint32_t> bits;for(std::uint32_t i=0;i<2*ln-1;++i)bits.push_back(ln-1-(i<ln?i:2*ln-2-i));std::vector<std::uint32_t> sizes(ln/lt-1,lt);sizes.push_back(2*lt-1);sizes.insert(sizes.end(),ln/lt-1,lt);std::uint32_t off=0;for(auto count:sizes){std::uint32_t mask=0;for(std::uint32_t s=0;s<count;++s)mask|=UINT32_C(1)<<bits[off+s];std::vector<std::vector<std::uint32_t>> layer;for(std::uint32_t key=0;key<n;++key)if((key&mask)==0){std::vector<std::uint32_t> g;for(std::uint32_t wire=0;wire<n;++wire)if((wire&~mask)==key)g.push_back(wire);if(g.size()!=t)throw std::logic_error("Benes group");layer.push_back(g);}r.groups.push_back(layer);off+=count;}return r;}
std::uint64_t protocol_i_benes_translation_count(const ProtocolIBenesLayout& l){return static_cast<std::uint64_t>(l.d)*l.n/l.t;}
ProtocolIBenesDecomposition protocol_i_benes_decompose(const ProtocolIPermutation& p,std::uint32_t t){protocol_i_validate_permutation(p);auto l=protocol_i_benes_layout(static_cast<std::uint32_t>(p.size()),t);const auto n=l.n,ln=lg(n);std::vector<ProtocolIPermutation> stages(2*ln-1,protocol_i_identity_permutation(n));auto forward=protocol_i_inverse_permutation(p);std::vector<std::pair<std::uint32_t,std::uint32_t>> map;for(std::uint32_t i=0;i<n;++i)map.push_back({i,forward[i]});route(0,ln,map,stages);std::vector<std::uint32_t> bits;for(std::uint32_t i=0;i<2*ln-1;++i)bits.push_back(ln-1-(i<ln?i:2*ln-2-i));std::vector<std::uint32_t> sizes(ln/lg(t)-1,lg(t));sizes.push_back(2*lg(t)-1);sizes.insert(sizes.end(),ln/lg(t)-1,lg(t));ProtocolIBenesDecomposition out{l,{}};std::uint32_t off=0;for(std::uint32_t layer=0;layer<l.d;++layer){auto combined=protocol_i_identity_permutation(n);for(std::uint32_t s=0;s<sizes[layer];++s)combined=protocol_i_compose_permutation(stages[off+s],combined);ProtocolIBenesLayer entry{combined,{}};for(const auto&g:l.groups[layer]){ProtocolIPermutation local(l.t);for(std::uint32_t i=0;i<l.t;++i){std::uint32_t j=0;while(j<l.t&&g[j]!=combined[g[i]])++j;if(j==l.t)throw std::logic_error("Benes leaves group");local[i]=j;}entry.local_permutations.push_back(local);}out.layers.push_back(entry);off+=sizes[layer];}auto total=protocol_i_identity_permutation(n);for(const auto&x:out.layers)total=protocol_i_compose_permutation(x.permutation,total);if(total!=p)throw std::logic_error("Benes compose");return out;}
}  // namespace moe_topk
